mapper.select:
SELECT todo.* FROM sys_im_todo_mapping todo
INNER JOIN sys_message_delivery delivery ON delivery.tenant_id = todo.tenant_id AND delivery.delivery_id = todo.delivery_id
WHERE todo.tenant_id = #{tenantId} AND delivery.record_id = #{recordId}

SELECT todo.*, COALESCE(NULLIF(member.nick_name, ''), member.user_name, '已移除账号') AS receiver_name
FROM sys_im_todo_mapping todo
LEFT JOIN sys_user member ON member.tenant_id = todo.tenant_id AND member.user_id = todo.receiver_user_id AND member.deleted = 0
WHERE todo.tenant_id = #{tenantId} AND todo.config_id = #{configId}
ORDER BY todo.mapping_id DESC LIMIT #{offset}, #{limit}
